#!/usr/bin/env bash
# Question 4: Busiest node. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/top
mkdir -p /opt/course/top
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
busy=$(shuf -e worker-1 worker-2 -n 1)
for i in 1 2; do
  kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"burner-'"$i"'","namespace":"'"${Q4_NS}"'","labels":{"app":"perf"}},"spec":{"nodeName":"'"$busy"'","containers":[{"name":"app","image":"busybox:1.36","command":["sh","-c","while true; do :; done"],"resources":{"limits":{"cpu":"800m","memory":"32Mi"}}}]}}' >/dev/null
done
kubectl -n "${Q4_NS}" wait --for=condition=Ready pod -l app=perf --timeout=180s >/dev/null
sleep 45
for _ in $(seq 1 30); do
  [[ "$(kubectl top node --sort-by=cpu --no-headers 2>/dev/null | head -1 | awk '{print $1}')" == "$busy" ]] && break
  sleep 5
done
: "${Q4_NS}"
